  ('KIM-0019', 'Qeyri-üzvi kimya', 'Qeyri-üzvi maddələrin sinifləri', 'qapali', 'Verilmiş duzun adını və tipini müəyyən edin. $\mathrm{MgHPO_{4}}$ Duzun tipi Adı', 'KIM-0019.png', '{"A": "maqnezium-dihidroortofosfat turş", "B": "maqnezium-hidroortofosfat turş", "C": "maqnezium-ortofosfat normal", "D": "maqnezium-hidroortofosfat normal", "E": "maqnezium-metafosfat qarışıq"}', 'B', '3', '$\mathrm{MgHPO_{4}}$ – maqnezium-hidroortofosfat, turş duzdur', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №49', 'KIM-0019_izah.png'),
  ('KIM-0020', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'qapali', 'Hansı duzun termiki parçalanmasından həm əsasi, həm də turşu oksidi əmələ gəlir?', NULL::text, '{"A": "$\\mathrm{Cu(NO_{3})_{2}}$", "B": "$\\mathrm{NaNO_{3}}$", "C": "$\\mathrm{AgNO_{3}}$", "D": "$\\mathrm{NH_{4}NO_{3}}$", "E": "$\\mathrm{KNO_{3}}$"}', 'A', '3', '$\mathrm{Cu(NO_{3})_{2} \rightarrow CuO}$ (əsasi oksid) + $\mathrm{NO_{2}}$ (turşu oksidi) + $\mathrm{O_{2}}$ $\mathrm{NaNO_{3} \rightarrow NaNO_{2} + O_{2}}$ $\mathrm{AgNO_{3} \rightarrow Ag + NO_{2} + O_{2}}$ $\mathrm{NH_{4}NO_{3} \rightarrow N_{2}O + H_{2}O}$ $\mathrm{KNO_{3} \rightarrow KNO_{2} + O_{2}}$', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №50', 'KIM-0020_izah.png'),
  ('KIM-0021', 'Qeyri-üzvi kimya', 'Metallar', 'qapali', '$\mathrm{Fe}$ $\mathrm{Ag}$ $\mathrm{Zn}$ Hər 3 qabda 200 q 16%-li $\mathrm{CuSO_{4}}$ məhlulu olduğunu nəzərə alaraq, $\mathrm{CuSO_{4}}$ məhlulu ilə metal lövhələrin tam reaksiyası zamanı alınan misin kütlələri cəmini qramla hesablayın. $\mathrm{M_{r}(CuSO_{4})=160,}$ $\mathrm{A_{r}(Cu)=64}$', 'KIM-0021.png', '{"A": "12,8", "B": "25,6", "C": "128", "D": "64", "E": "33,6"}', 'B', '3', 'Hər 3 qabda $\mathrm{CuSO_{4}}$ – ün kütləsi: $\mathrm{m(CuSO_{4})}$ = 200 ⋅ 0,16 = 32 q 32 q x q $\mathrm{Fe + CuSO_{4} \rightarrow FeSO_{4} + Cu}$ x = 12,8 q 160 q 64 q $\mathrm{Ag + CuSO_{4}}$ → reaksiya getmir 32 q y q $\mathrm{Zn + CuSO_{4} \rightarrow ZnSO_{4} + Cu}$ y = 12,8 q 160 q 64 q Reaksiyalardan alınan $\mathrm{Cu}$-un kütləsi = 12,8 + 12,8 = 25,6 q', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №51', 'KIM-0021_izah.png'),
  ('KIM-0023', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'aciq_eded', 'Bərabər mol nisbətində götürülən butadien-1,3 və stiroldan alınan birgə polimerin kütləsi 316 kq-dır. Polimerləşmə reaksiyasına neçə kq stirol daxil olmuşdur? $\mathrm{M_{r}(C_{4}H_{6})}$ =54, $\mathrm{M_{r}(C_{6}H_{5}}$ $\mathrm{CH}$ $\mathrm{CH_{2})}$ =104', NULL::text, NULL::text, '208', '3', 'Birgə polimerləşmə reaksiyasında butadien-1,3 və stirol 2 : 2 nisbətində götürüldükdə 2 ⋅ 54 + 2 ⋅ 104 = 316 kq polimer əmələ gəlir. Reaksiyaya 208 kq stirol daxil olub.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №53', 'KIM-0023_izah.png'),
  ('KIM-0024', 'Üzvi kimya', 'Alkenlər və alkadienlər', 'aciq_eded', 'Etilen və asetilendən ibarət qaz qarışığının 12 molunun tam hidrogenləşməsinə 20 mol $\mathrm{H_{2}}$ sərf olunmuşsa, ilkin qaz qarışığında neçə mol asetilen olmuşdur?', NULL::text, NULL::text, '8', '3', 'Etilen və asetilendən ibarət 12 mol qaz qarışığında etilenin mol sayını x, asetilenin mol sayını y mol qəbul etsək x + y = 12 olur. Etilenin 1 molunun tam hidrogenləşməsinə 1 mol $\mathrm{H_{2}}$ ,asetilenin 1 molunun tam hidrogenləşməsinə isə 2 mol $\mathrm{H_{2}}$ sərf olunur: x + y = 12 x + 2y = 20 x = 4 y = 8 (Deməli ilkin qarışıqda 8 mol asetilen olmuşdur)', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №54', 'KIM-0024_izah.png'),
  ('KIM-0026', 'Ümumi kimya', 'Məhlullar', 'aciq_eded', '$\mathrm{H_{2}SO_{4}}$ məhlulunun kütləsi, q Artıq miqdar $\mathrm{BaCl_{2}}$ məhlulu ilə reaksiyadan alınan çöküntünün kütləsi, q 49 23,3 Başlanğıc məhlulda sulfat turşusunun kütlə payını (% ilə) hesablayın. $\mathrm{M_{r}(H_{2}SO_{4})=98}$; $\mathrm{M_{r}(BaSO_{4})=233}$', 'KIM-0026.png', NULL::text, '20', '3', 'x q ------------------- 23,3 q $\mathrm{H_{2}SO_{4} + BaCl_{2} \rightarrow BaSO_{4}}$ ↓ + $\mathrm{2HCl}$ x = 9,8 q $\mathrm{H_{2}SO_{4}}$ 98 q ------------------- 233 q Məhlulda sulfat turşusunun kütlə payı = (9,8 : 49) ⋅ 100 = 20%', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №56', 'KIM-0026_izah.png'),
  ('KIM-0031', 'Üzvi kimya', 'Karbon turşuları', 'qapali', 'Maddə Molekulunda σ(C–H) rabitələrinin sayı Siniflərarası izomerinin hidroliz məhsulları $\mathrm{C_{n}H_{2n+1}COOH}$ 5 X+Y Y “gümüş-güzgü” reaksiyasına daxil olursa, X molekulunda atomların ümumi sayını hesablayın.', 'KIM-0031.png', '{"A": "5", "B": "12", "C": "6", "D": "9", "E": "8"}', 'D', '3', '2n + 1 = 5 2n = 4 n = 2 $\mathrm{C_{2}H_{5}COOH}$ turşusu ilə siniflərarası izomer olan maddənin hidroliz tənliyi: $\mathrm{HCOOC_{2}H_{5}+}$ $\mathrm{H_{2}O \Leftrightarrow HCOOH + C_{2}H_{5}OH}$ $\mathrm{HCOOH}$ “gümüş-güzgü” reaksiyasına daxil olduğu üçün X maddəsi $\mathrm{C_{2}H_{5}OH}$-dır və molekulunda 9 atomu var.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №31', 'KIM-0031_izah.png'),
  ('KIM-0032', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'qapali', 'Eyni kütlədə götürülmüş hidrogen və etandan ibarət qarışığın ümumi mol miqdarı 16 olarsa, hansı ifadələr doğrudur? $\mathrm{M_{r}(H_{2})=2,}$ $\mathrm{M_{r}(C_{2}H_{6})=30}$ I. Qarışığın ümumi kütləsi 60 qramdır II. Qarışıqda etanın həcmi 22,4 l-dir (n.ş.) III. Qarışıqda hidrogenin həcmi 22,4 l-dir (n.ş.)', NULL::text, '{"A": "yalnız II", "B": "I, III", "C": "I, II", "D": "II, III", "E": "yalnız I"}', 'C', '3', '16 30 2 15 16 30 16 16 30 30 m m m m m m + = + = = = Qarışığın ümumi kütləsi 30 + 30 = 60 q 30 q $\mathrm{C_{2}H_{6}}$ = 1 mol = 22,4 l 30 q $\mathrm{H_{2}}$ = 15 mol = 336 l', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №32', 'KIM-0032_izah.png'),
  ('KIM-0033', 'Ümumi kimya', 'Kimyəvi rabitə və hibridləşmə', 'qapali', 'Maddələr Molekulunda kimyəvi rabitələrin yaranmasında iştirak edən hibrid orbitallarının sayı X 4 Y 3 Z 2 X, Y və Z maddələrini müəyyən edin. X Y Z', 'KIM-0033.png', '{"A": "$\\mathrm{CH_{4}}$ $\\mathrm{NH_{3}}$ $\\mathrm{H_{2}O}$", "B": "$\\mathrm{CH_{4}}$ $\\mathrm{H_{2}O}$ $\\mathrm{NH_{3}}$", "C": "$\\mathrm{H_{2}O}$ $\\mathrm{NH_{3}}$ $\\mathrm{CH_{4}}$", "D": "$\\mathrm{NH_{3}}$ $\\mathrm{H_{2}O}$ $\\mathrm{CH_{4}}$", "E": "$\\mathrm{NH_{3}}$ $\\mathrm{CH_{4}}$ $\\mathrm{H_{2}O}$"}', 'A', '3', 'Hər üç molekulda mərkəzi atom $\mathrm{sp^{3}}$ hibrid halında olub 4 hibrid orbitalına malikdir. $\mathrm{CH_{4}}$ molekulunda 4 hibrid orbitalının hamısı, $\mathrm{NH_{3}}$ molekulunda 3-ü, $\mathrm{H_{2}O}$ molekulunda isə 2-si rabitələrin yaranmasında iştirak edir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №33', 'KIM-0033_izah.png'),
  ('KIM-0034', 'Ümumi kimya', 'Elektroliz', 'qapali', 'Duzun tam elektrolizi zamanı Y elektrodunda əmələ gələn maddənin kütləsini (q) hesablayın. $\mathrm{A_{r}(Cu)=64,}$ $\mathrm{A_{r}(S)=32,}$ $\mathrm{A_{r}(O)=16,}$ $\mathrm{A_{r}(H)=1}$ X Y + – 400 q 20 %-li $\mathrm{CuSO_{4}}$ suda məhlulu', 'KIM-0034.png', '{"A": "32", "B": "16", "C": "64", "D": "48", "E": "8"}', 'A', '3', 'Şəkildən göründüyü kimi Y elektrodu katoddur (mənfi yüklü olduğu üçün) və elektroliz prosesi zamanı bu elektrodda $\mathrm{Cu}$ alınır. (400⋅20) : 100 = 80 q $\mathrm{CuSO_{4}}$ 80 q x q $\mathrm{2CuSO_{4} + 2H_{2}O}$ → 2Cu + $\mathrm{2H_{2}SO_{4} + O_{2}}$ 2·160 q 2·64 q 80 q $\mathrm{CuSO_{4}-------}$ x q $\mathrm{Cu}$ 2·160 q $\mathrm{CuSO_{4}----}$ 2·64 q $\mathrm{Cu}$ x = 32 q $\mathrm{Cu}$', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №34', 'KIM-0034_izah.png'),
  ('KIM-0035', 'Qeyri-üzvi kimya', 'Qeyri-üzvi birləşmələr arasında genetik əlaqə', 'qapali', '$\mathrm{H_{2}SO_{4}}$ (qatı) + $\mathrm{Na}$ → X +Z,t → S $\mathrm{+O^{2}}$ → , t, Z – $\mathrm{(Na_{2}SO_{4}+Y)}$ –Y X, Y və Z maddələrini müəyyən edin. X Y Z', 'KIM-0035.png', '{"A": "$\\mathrm{H_{2}S}$ $\\mathrm{SO_{2}}$ $\\mathrm{H_{2}O}$", "B": "$\\mathrm{SO_{2}}$ $\\mathrm{H_{2}O}$ $\\mathrm{H_{2}S}$", "C": "$\\mathrm{SO_{2}}$ $\\mathrm{H_{2}S}$ $\\mathrm{H_{2}O}$", "D": "$\\mathrm{H_{2}O}$ $\\mathrm{H_{2}S}$ $\\mathrm{SO_{2}}$", "E": "$\\mathrm{H_{2}S}$ $\\mathrm{H_{2}O}$ $\\mathrm{SO_{2}}$"}', 'E', '3', '$\mathrm{H_{2}SO_{4}}$ (qatı) + $\mathrm{Na \rightarrow H_{2}S + SO \rightarrow ^{2},t}$ S $\mathrm{+O^{2},}$ → t, $\mathrm{SO_{2} - (Na_{2}SO_{4}+H_{2}O) - H_{2}O}$ Sxemə əsasən X – $\mathrm{H_{2}S,}$ Y- $\mathrm{H_{2}O,}$ Z- $\mathrm{SO_{2}}$', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №35', 'KIM-0035_izah.png'),
  ('KIM-0036', 'Üzvi kimya', 'Spirtlər', 'qapali', 'Etil spirti və 9,2 q qliserindən ibarət qarışığın artıq miqdarda götürülmüş natriumla reaksiyasından 5,6 l (n.ş.) hidrogen alınmışdır. Qarışıqda etil spirtinin kütləsini (qram ilə) hesablayın. $\mathrm{M_{r}(C_{2}H_{5}OH)=46,}$ $\mathrm{M_{r}(C_{3}H_{5}(OH)_{3})=92}$', NULL::text, '{"A": "10,2", "B": "14,2", "C": "9,2", "D": "23,0", "E": "16,8"}', 'C', '3', '9,2 q x l $\mathrm{2C_{3}H_{5}(OH)_{3}+}$ 6Na → $\mathrm{2C_{3}H_{5}(ONa)_{3}+}$ $\mathrm{3H_{2}}$ 2·92 q 67,2 l 9,2 q qliserin--------- x l $\mathrm{H_{2}}$ 2·92q qliserin--------- 67,2 l $\mathrm{H_{2}}$ x = 3,36 l 5,6 l - 3,36 l = 2,24 l x q 2,24 $\mathrm{2C_{2}H_{5}OH}$ + 2Na → $\mathrm{2C_{2}H_{5}ONa + H_{2}}$ 2·46 22,4 x q etil spirti------------ 2,24 l $\mathrm{H_{2}}$ 2·46 q etil spirti --------- 22,4 l $\mathrm{H_{2}}$ x = 9,2 q', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №36', 'KIM-0036_izah.png'),
  ('KIM-0037', 'Ümumi kimya', 'Elektrolitik dissosiasiya və ion mübadiləsi', 'qapali', 'Ammonium-sulfatın hansı maddələrin suda məhlulları ilə reaksiyası axıra qədər gedir? I. Barium-xlorid II. Xlorid turşusu III. Natrium-hidroksid IV. Kalium-nitrat', NULL::text, '{"A": "I və IV", "B": "II və III", "C": "II və IV", "D": "III və IV", "E": "I və III"}', 'E', '3', 'İon mübadilə reaksiyası zəif dissosiasiya edən maddə (əsasən çöküntü, qaz, su) alınan zaman axıra qədər gedir. I. $\mathrm{(NH_{4})_{2}SO_{4} + BaCl_{2} \rightarrow BaSO_{4}}$ ↓ + $\mathrm{NH_{4}Cl}$ II. $\mathrm{(NH_{4})_{2}SO_{4} + HCl}$ → reaksiya getmir III. $\mathrm{(NH_{4})_{2}SO_{4} + NaOH \rightarrow Na_{2}SO_{4} + NH_{3}}$ ↑ + $\mathrm{H_{2}O}$ IV. $\mathrm{(NH_{4})_{2}SO_{4} + KNO_{3}}$ → reaksiya axıra qədər getmir', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №37', 'KIM-0037_izah.png'),
  ('KIM-0038', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'qapali', 'X +H → $\mathrm{_{2}}$ $\mathrm{C_{2}H_{5}OH + CuO}$ → X X maddəsini müəyyən edin.', 'KIM-0038.png', '{"A": "$\\mathrm{HCOOH}$", "B": "$\\mathrm{CH_{3}}$ $\\mathrm{CH_{2}}$ C O H", "C": "$\\mathrm{CH_{3}}$ C O $\\mathrm{OH}$", "D": "$\\mathrm{CH_{3}}$ C O H", "E": "$\\mathrm{CO}$"}', 'D', '3', '$\mathrm{CH_{3}CHO + H_{2} \rightarrow CH_{3}CH_{2}OH}$ $\mathrm{CH_{3}CH_{2}OH + CuO \rightarrow CH_{3}CHO + Cu + H_{2}O}$', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №38', 'KIM-0038_izah.png'),
  ('KIM-0039', 'Üzvi kimya', 'Aromatik karbohidrogenlər', 'qapali', 'Benzol və toluoldan ibarət 20 q qarışığın $\mathrm{KMnO_{4}}$-ün suda məhlulu ilə oksidləşməsi zamanı üzvi maddələrdən biri tam sərf olunmuş və 12,2 q turşu alınmışdır. İlkin qarışıqda benzolun kütlə payını (%-lə) hesablayın. $\mathrm{M_{r}(C_{6}H_{6})=78,}$ $\mathrm{M_{r}(C_{7}H_{8})=92,}$ $\mathrm{M_{r}(C_{6}H_{5}COOH)=122}$', NULL::text, '{"A": "14", "B": "54", "C": "34", "D": "24", "E": "44"}', 'B', '3', 'Benzoldan fərqli olaraq toluol $\mathrm{KMnO_{4}}$-ün suda məhlulu ilə oksidləşir. x q 12,2 q $\mathrm{C_{6}H_{5}CH_{3}+3[O] \rightarrow C_{6}H_{5}COOH + H_{2}O}$ 92 q 122 q x q toluol------------ 12,2 q turşu 92 q toluol------------122 q turşu x = 9,2 q 20-9,2=10,8 (10,8:20)·100%=54%', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №39', 'KIM-0039_izah.png'),
  ('KIM-0040', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', 'Tərkibində mürəkkəb efir qrupu olan hansı irimolekullu birləşmə polikondensləşmə reaksiyası ilə alınır?', NULL::text, '{"A": "kapron", "B": "poliizopren", "C": "fenolformaldehid qətranı", "D": "lavsan", "E": "polimetilmetakrilat"}', 'D', '3', 'Lavsan və polimetilmetakrilatın tərkibində mürəkkəb efir qrupları var. Lakin polimetilmetakrilat polimerləşmə reaksiyası ilə, lavsan isə polikondensləşmə reaksiyası ilə alınır.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №40', 'KIM-0040_izah.png'),
  ('KIM-0041', 'Ümumi kimya', 'Reaksiya sürəti və kimyəvi tarazlıq', 'qapali', 'Eyni temperaturda bərabər həcmli qapalı qablarda baş verən reaksiyaların sürətlərini müqayisə edin. $\mathrm{A_{r}(N)=14,}$ $\mathrm{A_{r}(H)=1}$ 14 q $\mathrm{N_{2}}$ + 14 q $\mathrm{H_{2}}$ 14 q $\mathrm{N_{2}}$ + 14 mol $\mathrm{H_{2}}$ 14 mol $\mathrm{N_{2}}$ + 14 q $\mathrm{H_{2}}$ $\mathrm{v_{1}}$ $\mathrm{v_{2}}$ $\mathrm{v_{3}}$', 'KIM-0041.png', '{"A": "$\\mathrm{v_{1}>}$ $\\mathrm{v_{2}>}$ $\\mathrm{v_{3}}$", "B": "$\\mathrm{v_{2}>}$ $\\mathrm{v_{3}>}$ $\\mathrm{v_{1}}$", "C": "$\\mathrm{v_{3}>v_{2}>v_{1}}$", "D": "$\\mathrm{v_{1}=v_{2}=v_{3}}$", "E": "$\\mathrm{v_{3}>}$ $\\mathrm{v_{1}>}$ $\\mathrm{v_{2}}$"}', 'C', '3', 'Reaksiya eyni temperaturda və eyni həcmli qablarda baş verir. Eyni temperaturda eyni maddələr arasında baş verdiyi üçün sürət sabiti (k) dəyişmir. Kütlələrin təsiri qanununu tətbiq edərək sürətləri müqayisə edək. Qabların həcmləri bərabər olduğundan müqayisə zamanı qatılıq əvəzinə mol miqdarından istifadə edə bilərik. 14 q $\mathrm{N_{2}}$ = 0,5 mol 14 q $\mathrm{H_{2}}$ = 7 mol $\mathrm{v_{1} = k\cdot [N_{2}]\cdot [H_{2}]^{3}=}$ $\mathrm{k\cdot 0,5\cdot 7^{3}}$ $\mathrm{v_{2} = k\cdot [N_{2}]\cdot [H_{2}]^{3}=}$ $\mathrm{k\cdot 0,5\cdot 14^{3} = k\cdot 4\cdot 7^{3}}$ $\mathrm{v_{3} = k\cdot [N_{2}]\cdot [H_{2}]^{3}=}$ $\mathrm{k\cdot 14\cdot 7^{3}}$ İfadələrin müqayisəsindən aydın olur ki, $\mathrm{v_{3}>v_{2}>v_{1}}$', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №41', 'KIM-0041_izah.png'),
  ('KIM-0042', 'Qeyri-üzvi kimya', 'Halogenlər', 'qapali', 'Eyni mol miqdarda götürülmüş hansı metal ilə reaksiyaya daha çox xlorid turşusu sərf olunar?', NULL::text, '{"A": "$\\mathrm{Na}$", "B": "$\\mathrm{Zn}$", "C": "$\\mathrm{Al}$", "D": "$\\mathrm{Mg}$", "E": "$\\mathrm{Fe}$"}', 'C', '3', 'n valentli metalın bir molu n mol $\mathrm{HCl}$ ilə reaksiyaya daxil olur. Deməli eyni mol miqdarda götürülmüş daha yüksək valentli metal ilə reaksiyaya daha çox xlorid turşusu sərf olunar. $\mathrm{Na}$ I valentli , $\mathrm{Zn}$ və $\mathrm{Mg-II}$ valentli $\mathrm{Al}$ III valentli, $\mathrm{Fe}$ isə II, III valentlidir. Lakin $\mathrm{Fe}$ xlorid turşusu ilə $\mathrm{FeCl_{2}}$ əmələ gətirdiyindən cavab $\mathrm{Al}$ olur.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №42', 'KIM-0042_izah.png'),
  ('KIM-0046', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'qapali', 'Maddə Qatı $\mathrm{HNO_{3}}$ ilə reaksiya məhsulu X $\mathrm{X(NO_{3})_{2}+NO_{2}+H_{2}O}$ Y $\mathrm{YO_{2}+NO_{2}+H_{2}O}$ Z $\mathrm{H_{2}ZO_{4}+NO_{2}+H_{2}O}$ X, Y və Z-i müəyyən edin. X Y Z', 'KIM-0046.png', '{"A": "$\\mathrm{Fe}$ S C", "B": "$\\mathrm{Cu}$ C S", "C": "$\\mathrm{Cu}$ P S", "D": "$\\mathrm{Cu}$ S P", "E": "$\\mathrm{Fe}$ C P"}', 'B', '3', '$\mathrm{Fe + HNO_{3} \rightarrow Fe(NO_{3})_{3}+}$ $\mathrm{NO + H_{2}O}$ $\mathrm{Cu + HNO_{3} \rightarrow Cu(NO_{3})_{2}+}$ $\mathrm{NO_{2} + H_{2}O}$ (X maddəsinə uyğun) C + $\mathrm{HNO_{3} \rightarrow CO_{2}+}$ $\mathrm{NO_{2} + H_{2}O}$ (Y maddəsinə uyğun) P + $\mathrm{HNO_{3} \rightarrow H_{3}PO_{4} + NO_{2} + H_{2}O}$ S + $\mathrm{HNO_{3} \rightarrow H_{2}SO_{4}+}$ $\mathrm{NO_{2} + H_{2}O}$ (Z maddəsinə uyğun)', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №46', 'KIM-0046_izah.png'),
  ('KIM-0048', 'Ümumi kimya', 'Atomun quruluşu və dövri sistem', 'qapali', 'Dördüncü dövrün əlavə yarımqrup elementi Atomunda elektronların ümumi sayı s p d X a+2 a+7 a X elementi üçün hansı ifadələr doğrudur? 1. ... $\mathrm{3d^{4}4s^{2}}$ qısa elektron formuluna malikdir 2. VI B qrupunda yerləşir 3. 6 cütləşməmiş (tək) elektronu var 4. Qeyri-metaldır', 'KIM-0048.png', '{"A": "2, 3", "B": "1, 3", "C": "1, 4", "D": "2, 4", "E": "1, 2"}', 'A', '3', 'Dördüncü dövrün əlavə yarımqrup elementlərinin hər birində 12 p elektronu olduğundan: a + 7 = 12 a = 5 X atomunda elektronların ümumi sayı: a+2 + a+7 + a = 24 24 protonu olan element (X). ... $\mathrm{3d^{5}4s^{1}}$ qısa elektron formuluna malikdir, 6 tək elektronu var və metaldır, VI B qrupunda yerləşir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №48', 'KIM-0048_izah.png'),
  ('KIM-0049', 'Qeyri-üzvi kimya', 'Hidrogen, oksigen, su', 'qapali', '$\mathrm{KMnO_{4}}$ → → Y $\mathrm{KClO_{3}}$ t $\mathrm{MnO_{2},}$ t + $\mathrm{HCl}$ X el-z Müəyyən şəraitdə hansı reaksiyalar baş verir? 1. X+Cu → 2. $\mathrm{Y+CO}$ → 3. X+S → 4. $\mathrm{Y+NH_{3}}$ → 5. $\mathrm{X+F_{2}}$ →', 'KIM-0049.png', '{"A": "2, 4, 5", "B": "1, 2, 5", "C": "1, 2, 3", "D": "3, 4, 5", "E": "1, 3, 4"}', 'A', '3', '$\mathrm{2KMnO_{4} \rightarrow K_{2}MnO_{4} + MnO_{2} + O_{2}}$ $\mathrm{KClO_{3}+}$ $\mathrm{6HCl \rightarrow 5KCl + 3H_{2}O + 3Cl_{2}}$ $\mathrm{2H_{2}O \rightarrow 2H_{2} + O_{2}}$ Deməli X maddəsi $\mathrm{H_{2}O,}$ Y maddəsi $\mathrm{O_{2}}$-dir. 1. $\mathrm{H_{2}O + Cu}$ → reaksiya getmir 2. $\mathrm{O_{2}+}$ $\mathrm{2CO \rightarrow 2CO_{2}}$ 3. $\mathrm{H_{2}O}$ + S → reaksiya getmir 4. $\mathrm{5O_{2}+}$ $\mathrm{4NH_{3} \rightarrow 4NO + 6H_{2}O}$ 5. $\mathrm{2H_{2}O+}$ $\mathrm{2F_{2} \rightarrow 4HF + O_{2}}$', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №49', 'KIM-0049_izah.png'),
  ('KIM-0051', 'Qeyri-üzvi kimya', 'Halogenlər', 'qapali', 'Halogenlər Nisbi atom kütləsi Atom radiusu X $\mathrm{A_{r}(X)}$ $\mathrm{r_{1}}$ Y $\mathrm{A_{r}(Y)}$ $\mathrm{r_{2}}$ Nə doğrudur?', 'KIM-0051.png', '{"A": "$\\mathrm{A_{r}(X)<A_{r}(Y)}$ olarsa, $\\mathrm{r_{1}=r_{2}}$", "B": "$\\mathrm{A_{r}(X)<A_{r}(Y)}$ olarsa, $\\mathrm{r_{1}<r_{2}}$", "C": "$\\mathrm{A_{r}(X)>A_{r}(Y)}$ olarsa, $\\mathrm{r_{1}=r_{2}}$", "D": "$\\mathrm{A_{r}(X)<A_{r}(Y)}$ olarsa, $\\mathrm{r_{1}>r_{2}}$", "E": "$\\mathrm{A_{r}(X)>A_{r}(Y)}$ olarsa, $\\mathrm{r_{1}<r_{2}}$"}', 'B', '3', 'F, $\mathrm{Cl}$, $\mathrm{Br}$, I istiqamətində halogenlərin nisbi atom kütlələri və atom radiusları artır. Bu səbəbdən $\mathrm{A_{r}(X)<A_{r}(Y)}$ olarsa, $\mathrm{r_{1}<r_{2,}}$ və $\mathrm{A_{r}(X)}$ $\mathrm{>A_{r}(Y)}$ olarsa, $\mathrm{r_{1}>r_{2}}$ şərtləri ödənilir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №51', 'KIM-0051_izah.png'),
  ('KIM-0053', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'aciq_eded', 'Müəyyən şəraitdə hidrogen və azot arasında baş verən reaksiya zamanı reaksiyaya daxil olan və alınan qaz qarışığının ümumi mol miqdarının (ν) zamandan asılı olaraq dəyişmə qrafikinə əsasən $\mathrm{t_{1}}$ anına qədər reaksiyaya daxil olmuş hidrogenin mol sayını hesablayın. ν, mol 120 96 $\mathrm{t_{1}}$ → t, san', 'KIM-0053.png', NULL::text, '36', '3', '$\mathrm{N_{2} + 3H_{2} \rightarrow 2NH_{3}}$ Reaksiya tənliyindən göründüyü kimi 1k + 3k = 4k mol qaz qarışığı reaksiyaya girən zaman 2k mol qaz əmələ gəlir. Reaksiyaya daxil olan və alınan qaz qarışığının ümumi mol miqdarının azalması 4k – 2k = 2k mol olur. Qrafikə əsasən isə azalma 120 – 96 = 24 moldur. 2k mol azalma-----------3k mol $\mathrm{H_{2}}$ 24 mol azalma-------- x mol $\mathrm{H_{2}}$ x = 36', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №53', 'KIM-0053_izah.png'),
  ('KIM-0055', 'Qeyri-üzvi kimya', 'Qeyri-üzvi maddələrin sinifləri', 'aciq_eded', 'Reaksiyaya daxil olan maddələr Kütləsi, q Alınan duzun formulu $\mathrm{NaOH}$ 8 $\mathrm{NaH_{2}PO_{4}}$ $\mathrm{H_{3}PO_{4}}$ x x-i hesablayın. $\mathrm{M_{r}(NaOH)=40,}$ $\mathrm{M_{r}(H_{3}PO_{4})=98}$', 'KIM-0055.png', NULL::text, '19,6', '3', '8 q x q $\mathrm{NaOH + H_{3}PO_{4} \rightarrow NaH_{2}PO_{4}+}$ $\mathrm{H_{2}O}$ 40 q 98 q 8 q $\mathrm{NaOH}$ - - - - - - x q $\mathrm{H_{3}PO_{4}}$ 40 q $\mathrm{NaOH}$ - - - - - 98 q $\mathrm{H_{3}PO_{4}}$ x = 19,6 q', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №55', 'KIM-0055_izah.png'),
  ('KIM-0061', 'Üzvi kimya', 'Karbohidrogenlər (ümumi)', 'qapali', 'Tsiklopropan və propen üçün ümumi olan nədir?', NULL::text, '{"A": "quruluş formulları", "B": "molekulda siqma rabitələrin ümumi sayı", "C": "molekulda hibrid orbitalların sayı", "D": "molekulda atomlarının ümumi sayı", "E": "sənayedə alınma üsulları"}', 'D', '3', 'Həm tsiklopropan, həm də propenin kimyəvi formulu $\mathrm{C_{3}H_{6}}$-dır. Kimyəvi formuldan göründüyü kimi, molekulda atomlarının ümumi sayı eynidir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №31', 'KIM-0061_izah.png'),
  ('KIM-0062', 'Ümumi kimya', 'Kimyəvi tənliklər üzrə hesablamalar', 'qapali', '$\mathrm{CO}$ və $\mathrm{O_{2}}$-dən ibarət qaz qarışığı müəyyən şəraitdə reaksiyaya daxil olmuşdur. Qrafikə əsasən $\mathrm{\tau _{1}}$ anına qədər alınan $\mathrm{CO_{2}}$-nin həcmini (litrlə) hesablayın. 90 70 $\mathrm{\tau _{1}}$ → τ(zaman) V(l) qaz qarışığı', 'KIM-0062.png', '{"A": "40", "B": "15", "C": "20", "D": "5", "E": "10"}', 'A', '3', '$\mathrm{2CO + O_{2} \rightarrow 2CO_{2}}$ reaksiyası üzrə: Reaksiyaya daxil olan maddələrin həcmi =2+1=3 l Reaksiyadan alınan $\mathrm{CO_{2}}$ həcmi = 2 l Fərq = 3-2 = 1 litr Reaksiya tənliyi üzrə 1 litr fərq------2 litr $\mathrm{CO_{2}}$ 20 litr fərq-------x litr CO2/ alınır x = 40 litr', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №32', 'KIM-0062_izah.png'),
  ('KIM-0063', 'Ümumi kimya', 'Atomun quruluşu və dövri sistem', 'qapali', '$\mathrm{X^{3+}}$ ionundakı elektronların sayı azot atomunun $\mathrm{(_{7}N)}$ xarici elektron təbəqəsində olan elektronların sayından 2 dəfə çoxdursa, X atomunun dövri sistemdə mövqeyini müəyyən edin. Dövr Qrup Yarımqrup', 'KIM-0063.png', '{"A": "IV VI əlavə", "B": "III VII əsas", "C": "IV II əsas", "D": "III III əsas", "E": "III II əlavə"}', 'D', '3', 'Azot atomunun elektron formulu $\mathrm{_{7}N}$ .... $\mathrm{1s^{2}/2s^{2}}$ $\mathrm{2p^{3}.}$ Göründüyü kimi, azot atomunun xarici elektron təbəqəsində 5 elektron var. Onda $\mathrm{X^{3+}}$ ionunda 10 elektron var. Deməli, neytral X atomunda 13 elektron var. X atomunun elektron formulundan $\mathrm{(_{13}X}$ $\mathrm{1s^{2}/2s^{2}}$ $\mathrm{2p^{6}/3s^{2}}$ $\mathrm{3p^{1})}$ aydın olur ki, o dövri sistemdə III dövr, III qrupun əsas yarımqrupunda yerləşir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №33', 'KIM-0063_izah.png'),
  ('KIM-0064', 'Üzvi kimya', 'Alkanlar', 'qapali', '1 mol $\mathrm{C_{n}H_{2n+2}}$ alkanının xlor ilə reaksiyası zamanı hidrogen atomlarının ümumi sayının 60%-i əvəz olunur və 219 q $\mathrm{HCl}$ əmələ gəlir. n-i hesablayın. $\mathrm{M_{r}(HCl)=36,5}$', NULL::text, '{"A": "4", "B": "3", "C": "2", "D": "5", "E": "6"}', 'A', '3', 'Alkanlar xlorla əvəzetmə reaksiyasına daxil olur. Bu reaksiyalar zamanı neçə mol hidrogen atomu əvəzlənirsə, həmin miqdarda (mol) $\mathrm{HCl}$ alınır. Əmələ gələn $\mathrm{HCl}$-un miqdarı 219/36,5 =6 moldur. Əgər hidrogen atomlarının 60% faizi əvəz olunubsa, deməli alkan molekulunda 10 hidrogen atomu var. Molekulunda 10 hidrogen atomu olan alkan $\mathrm{C_{4}H_{10}}$-dur. (2n+2=10, n=4)', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №34', 'KIM-0064_izah.png'),
  ('KIM-0068', 'Ümumi kimya', 'Reaksiyaların təsnifatı və istilik effekti', 'qapali', 'Müəyyən miqdar metanın tam yanmasına 6 mol oksigen sərf edilmiş və 2640 kC istilik ayrılmışdır. Reaksiyanın istilik effektini (kC ilə) hesablayın.', NULL::text, '{"A": "1760", "B": "440", "C": "220", "D": "3520", "E": "880"}', 'E', '3', 'Metanın yanma reaksiyasının tənliyinə əsasən 6 mol 2640 kC ayrılır $\mathrm{CH_{4}+}$ $\mathrm{2O_{2} \rightarrow CO_{2} + 2H_{2}O}$ +Q kC 2 mol Q kC ayrılır Q=880 kC', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №38', 'KIM-0068_izah.png'),
  ('KIM-0069', 'Üzvi kimya', 'Mürəkkəb efirlər', 'qapali', 'Efirləşmə reaksiyasına daxil olan maddələr Molekulunda karbon atomlarının sayı Alınan mürəkkəb efir molekulunda siqma rabitələrin ümumi sayı Doymuş biratomlu spirt n x Doymuş birəsaslı karbon turşusu 2n x-i hesablayın.', 'KIM-0069.png', '{"A": "9n – 1", "B": "9n + 1", "C": "9n + 5", "D": "9n + 3", "E": "9n"}', 'B', '3', 'Efirləşmə reaksiyasından alınan mürəkkəb efir molekulunda karbon atomlarının ümumi sayı efiri əmələ gətirən spirt və karbon turşusunun molekulunda karbon atomlarının cəminə bərabərdir. Mürəkkəb efirlərin ümumi formulu $\mathrm{C_{y}H_{2y}O_{2}}$ olduğundan y=n+2n=3n karbon atomu olan mürəkkəb efirin formulunu $\mathrm{C_{3n}H_{6n}O_{2}}$ kimi göstərə bilərik. Mürəkkəb efir molekulunda siqma rabitələrin sayını hesabladıqda σ=3n+6n+2-1= 9n+1 alınır', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №39', 'KIM-0069_izah.png'),
  ('KIM-0070', 'Qeyri-üzvi kimya', 'Halogenlər', 'qapali', 'Halogenlər Kütləsi, q Halogenlə reaksiyaya sərf olunan natriumun kütləsi, q $\mathrm{X_{2}}$ a $\mathrm{m_{1}}$ $\mathrm{Y_{2}}$ a $\mathrm{m_{2}}$ $\mathrm{Z_{2}}$ a $\mathrm{m_{3}}$ $\mathrm{m_{2}>m_{3}>m_{1}}$ olarsa, halogenlərin reduksiyaedicilik qabiliyyətinin artma sırasını müəyyən edin (halogenlər reaksiyaya tam sərf olunur).', 'KIM-0070.png', '{"A": "$\\mathrm{Y_{2},}$ $\\mathrm{X_{2},}$ $\\mathrm{Z_{2}}$", "B": "$\\mathrm{Z_{2},}$ $\\mathrm{X_{2},}$ $\\mathrm{Y_{2}}$", "C": "$\\mathrm{Y_{2},}$ $\\mathrm{Z_{2},}$ $\\mathrm{X_{2}}$", "D": "$\\mathrm{X_{2},}$ $\\mathrm{Z_{2},}$ $\\mathrm{Y_{2}}$", "E": "$\\mathrm{X_{2},}$ $\\mathrm{Y_{2},}$ $\\mathrm{Z_{2}}$"}', 'C', '3', 'Dövri sistemdə halogenlərin qrup daxilində yuxarıdan aşağı getdikcə əmələ gətirdiyi bəsit maddələrin molyar kütləsi artdıqca onların reduksiyaedicilik qabiliyyəti artır. Ümumi şəkildə eyni kütlədə götürülmüş halogenlərin $\mathrm{Na}$ ilə reaksiyasına sərf olunan natriumun kütləsini aşağıdakı sxem üzrə hesablamaq olar: a m $\mathrm{Hlg_{2}}$ +2Na → 2NaHlg 46 = a m M M 46 Hesablamadan göründüyü kimi, molyar kütləsi az olan halogenlə reaksiyaya daha çox natrium sərf olunur.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №40', 'KIM-0070_izah.png'),
  ('KIM-0071', 'Ümumi kimya', 'Elektroliz', 'qapali', 'Duzun suda məhlulu Elektroliz zamanı katodda anodda elektrolit məhlulunda alınan birəsaslı turşunun mol sayı yalnız metal ayrılır ayrılan qazın həcmi (l, n.ş.) 11,2 x x-i hesablayın.', 'KIM-0071.png', '{"A": "1", "B": "0,5", "C": "2", "D": "4", "E": "1,5"}', 'C', '3', 'Cədvəldəki məlumatlara əsasən, elektrolizin ümumi tənliyini aşağıdakı kimi yazmaq olar: $\mathrm{4MeX_{n} + 2nH_{2}O}$ → 4Me + $\mathrm{nO_{2}}$ +4nHX 11,2 litr $\mathrm{O_{2}---------------a}$ mol HX n⋅22,4 litr $\mathrm{O_{2}---------}$ 4n mol HX a= 2 mol', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №41', 'KIM-0071_izah.png'),
  ('KIM-0072', 'Üzvi kimya', 'Spirtlər', 'qapali', '$\mathrm{+CH_{3}COOH,}$ t, H → $\mathrm{_{2}SO_{4}(q)}$ X $\mathrm{CH_{3}OH + HCl}$, t, $\mathrm{H_{2} \rightarrow SO_{4}}$ (q) Y – $\mathrm{H_{2}O - H_{2}O}$ X və Y maddələrini müəyyən edin. X Y', 'KIM-0072.png', '{"A": "$\\mathrm{CH_{4}}$ $\\mathrm{CH_{3}OCl}$", "B": "$\\mathrm{HCOOCH_{3}}$ $\\mathrm{CH_{3}Cl}$", "C": "$\\mathrm{CH_{3}COOCH_{3}}$ $\\mathrm{CH_{3}Cl}$", "D": "$\\mathrm{CH_{3}COOCH_{3}}$ $\\mathrm{CH_{3}OCl}$", "E": "$\\mathrm{CH_{4}}$ $\\mathrm{CH_{3}Cl}$"}', 'C', '3', '$\mathrm{CH_{3}OH + CH_{3}COOH}$ $\mathrm{CH \rightarrow _{3}COOCH_{3}+}$ $\mathrm{H_{2}O}$ $\mathrm{H_{2}SO_{4}(q),}$ t $\mathrm{CH_{3}OH + HCl}$ $\mathrm{CH \rightarrow _{3}Cl + H_{2}O}$ $\mathrm{H_{2}SO_{4}(q),t}$ Reaksiyalara əsasən X - $\mathrm{CH_{3}COOCH_{3,}Y}$ isə $\mathrm{CH_{3}Cl}$ maddəsidir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №42', 'KIM-0072_izah.png'),
  ('KIM-0073', 'Üzvi kimya', 'Aromatik karbohidrogenlər', 'qapali', 'Maddə Aqreqat halı $\mathrm{HNO_{3}}$ ilə reaksiya tipi Bir molekulunda atomların sayı X maye əvəzetmə 12 X maddəsini müəyyən edin.', 'KIM-0073.png', '{"A": "toluol", "B": "benzol", "C": "fenol", "D": "anilin", "E": "propen"}', 'B', '3', 'Toluol $\mathrm{(C_{7}H_{8})}$ molekulunda 15 atom var və mayedir. Benzol $\mathrm{(C_{6}H_{6})}$ molekulunda 12 atom var və mayedir, $\mathrm{HNO_{3}}$ ilə reaksiyanın tipi- əvəzetmə Fenol $\mathrm{(C_{6}H_{5}OH)}$ molekulunda 13 atom var və bərkdir. Anilin $\mathrm{(C_{6}H_{5}NH_{2})}$ molekulunda 14 atom var və mayedir. Propen $\mathrm{(C_{3}H_{6})}$ molekulunda 9 atom var və qazdır.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №43', 'KIM-0073_izah.png'),
  ('KIM-0074', 'Ümumi kimya', 'Reaksiya sürəti və kimyəvi tarazlıq', 'qapali', '$\mathrm{N_{2}+}$ $\mathrm{3H_{2} \Leftrightarrow 2NH_{3}+}$ Q reaksiyasında temperatur və təzyiqi necə dəyişmək lazımdır ki, tarazlıq ilkin maddələrin alınması istiqamətinə yerini dəyişsin? Temperatur Təzyiq', 'KIM-0074.png', '{"A": "artırmaq artırmaq", "B": "azaltmaq artırmaq", "C": "azaltmaq azaltmaq", "D": "dəyişməmək artırmaq", "E": "artırmaq azaltmaq"}', 'E', '3', 'Le-Şatelye prinsipinə görə tarazlıqda olan sistemə xaricdən təsir edildikdə kimyəvi tarazlıq sistemdə həmin təsirin azaldığı tərəfə yönəlir. Verilmiş dönən reaksiyada sola gedən reaksiya endotermikdir və sistemdə təzyiqin artması ilə baş verir. Bunlara əsasən , $\mathrm{N_{2}+}$ $\mathrm{3H_{2} \Leftrightarrow 2NH_{3}+}$ Q reaksiyasında tarazlığı ilkin maddələrin alınması istiqamətinə yönəltmək üçün temperaturu artırmaq, təzyiqi azaltmaq lazımdır.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №44', 'KIM-0074_izah.png'),
  ('KIM-0079', 'Üzvi kimya', 'Aminlər və aminturşular', 'qapali', 'O H $\mathrm{H_{2}N}$ $\mathrm{CH}$ C N $\mathrm{CH}$ C $\mathrm{CH_{3}}$ $\mathrm{CH_{3}}$ O $\mathrm{OH}$ Maddə üçün doğru ifadələr: 1. Qlisinin dipeptididir 2. α-alaninin dipeptididir 3. 1 molunun tam hidrolizinə 2 mol su sərf olunur 4. 1 molunun tam hidrolizindən 2 mol aminturşu əmələ → gəlir 5. Molekulunda 1 peptid rabitə var', 'KIM-0079.png', '{"A": "1, 3, 5", "B": "1, 2, 3", "C": "2, 3, 4", "D": "1, 3, 4", "E": "2, 4, 5"}', 'E', '3', 'Qeyd edilən maddə α-alaninin dipeptididir. Dipeptid molekulunda 1 peptid rabitəsi olur, bir molunun hidrolizi zamanı 1 mol su sərf olunur və 2 mol aminturşu əmələ gəlir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №49', 'KIM-0079_izah.png'),
  ('KIM-0080', 'Qeyri-üzvi kimya', 'Kükürd və birləşmələri', 'qapali', '0,2 mol $\mathrm{H_{2}S}$ 0,6 mol oksigen ilə $\mathrm{2H_{2}S + 3O_{2}t \rightarrow 2H_{2}O + 2SO_{2}}$ reaksiyasına tam daxil olur. Hansı ifadələr doğrudur? $\mathrm{M_{r}(H_{2}O)=18}$ I. 0,2 mol $\mathrm{SO_{2}}$ alınır II. 7,2 q $\mathrm{H_{2}O}$ alınır III. 0,3 mol $\mathrm{O_{2}}$ artıq qalır', NULL::text, '{"A": "II, III", "B": "I, III", "C": "yalnız I", "D": "I, II", "E": "yalnız III"}', 'B', '3', 'verilən: 0,2 mol 0,6 mol sərf olunan: 0,2 mol 0,3 mol x q y mol $\mathrm{2H_{2}S + 3O_{2}t \rightarrow 2H_{2}O + 2SO_{2}}$ 2 mol 3 mol 36 q 2 mol Verilmiş mol miqdarlarından aydındır ki, reaksiya zamanı $\mathrm{H_{2}S}$ tam sərf olunur. X=3,6 q $\mathrm{H_{2}O}$ ,Y =0,2 mol $\mathrm{SO_{2}}$ alınır . 0,3 mol $\mathrm{O_{2}}$ artıq qalır.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №50', 'KIM-0080_izah.png'),
  ('KIM-0081', 'Üzvi kimya', 'Karbohidratlar', 'qapali', 'm sayda asimmetrik karbon atomu olan sellülozanın tam yanmasından neçə mol karbon-dioksid alınar?', NULL::text, '{"A": "6m", "B": "1,5m", "C": "5m", "D": "3m", "E": "1,2m"}', 'E', '3', 'Sellülozanın makromolekulunda karbon atomlarının ümumi sayı 6n, asimmetrik karbon atomlarının sayı 5n-dir. Tənasüb qursaq: 5n -------------- 6n mol $\mathrm{CO_{2}}$ m------------------x mol $\mathrm{CO_{2}}$ x = 1,2m', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №51', 'KIM-0081_izah.png'),
  ('KIM-0082', 'Qeyri-üzvi kimya', 'Karbon və silisium', 'qapali', '$\mathrm{Si}$ $\mathrm{+X+H_{2}O}$ Y + $\mathrm{HCl}$ → Z – $\mathrm{H_{2} - NaCl}$ Z maddəsini müəyyən edin.', NULL::text, '{"A": "$\\mathrm{SiO_{2}}$", "B": "$\\mathrm{H_{2}SiO_{3}}$", "C": "$\\mathrm{SiH_{4}}$", "D": "$\\mathrm{H_{2}O}$", "E": "$\\mathrm{SiO}$"}', 'B', '3', 'Sxemdən göründüyü kimi, X - $\mathrm{NaOH}$, Y - $\mathrm{Na_{2}SiO_{3}-}$ dür. $\mathrm{Na_{2}SiO_{3} + 2HCl \rightarrow 2NaCl + H_{2}SiO_{3}(Z)}$', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №52', 'KIM-0082_izah.png'),
  ('KIM-0083', 'Qeyri-üzvi kimya', 'Metallar', 'aciq_eded', '4,6 q natriumun artıq miqdarda su ilə qarşılıqlı təsirindən ayrılan miqdarda hidrogen almaq üçün neçə qram dəmirə xlorid turşusu ilə təsir etmək lazımdır? $\mathrm{A_{r}(Fe)=56,}$ $\mathrm{A_{r}(Na)=23}$', NULL::text, NULL::text, '5,6', '3', '4,6 x 2Na + $\mathrm{2H_{2}O \rightarrow 2NaOH + H_{2}}$ 46 1 mol x=0,1 mol y 0,1 $\mathrm{Fe + 2HCl \rightarrow FeCl_{2} + H_{2}}$ 56 1 mol y = 5,6', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №53', 'KIM-0083_izah.png'),
  ('KIM-0084', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'aciq_eded', '3,3-dimetilbutanal molekulunda funksional qrupun kütlə payını (%-lə) hesablayın. $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(H)=1,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, NULL::text, '29', '3', '3,3-dimetilbutanalın kimyəvi formulu $\mathrm{C_{6}H_{12}O,}$ 1 molunun kütləsi 100 qramdır. Tərkibində olan $\mathrm{CHO}$ funksional qrupunun kütləsinin 29 qram olduğunu nəzərə alsaq, bu funksional qrupun kütlə payı 29% təşkil edir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №54', 'KIM-0084_izah.png'),
  ('KIM-0085', 'Ümumi kimya', 'Məhlullar', 'aciq_eded', 'Doymamış duz məhlulunun qatılığının (%) məhlulun kütləsindən (q) asılılıq qrafikinə əsasən doğru olmayan ifadələri müəyyən edin. c b a $\mathrm{m_{1}}$ m → $\mathrm{_{2}}$ mməh ω, % $\mathrm{X_{2}}$ $\mathrm{X_{1}}$ $\mathrm{X_{3}}$ 1. $\mathrm{X_{1} \rightarrow X_{2}}$ keçidi üçün məhlula yalnız duz əlavə olunur 2. $\mathrm{X_{1} \rightarrow X_{3}}$ keçidi üçün məhlula yalnız duz əlavə olunur 3. $\mathrm{X_{3} \rightarrow X_{1}}$ keçidi üçün məhluldan su buxarlanır 4. $\mathrm{X_{2} \rightarrow X_{1}}$ keçidi üçün məhlula su əlavə olunur', 'KIM-0085.png', NULL::text, '2,4', '3', '$\mathrm{1.X_{1} \rightarrow X_{2}}$ keçidi zamanı məhlulun qatılığı və kütləsi artmışdır. Deməli, məhlula duz əlavə olunub 2. $\mathrm{X_{1} \rightarrow X_{3}}$ keçidi zamanı məhlulun qatılığı azalır, kütləsi artır. Deməli, məhlula su əlavə olunub və ya həmin duzun fərqli qatılıqda məhlulu əlavə olunub. $\mathrm{3.X_{3} \rightarrow X_{1}}$ keçidi zamanı məhlulun qatılığı artır, kütləsi azalır. Deməli məhluldan su buxarlanır $\mathrm{4.X_{2} \rightarrow X_{1}}$ keçidi zamanı məhlula su əlavə olunsa idi , məhlulun kütləsi artacaqdır', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №55', 'KIM-0085_izah.png'),
  ('KIM-0086', 'Qeyri-üzvi kimya', 'Karbon və silisium', 'aciq_eded', 'Termiki parçalanmaya davamlı 25% kənar qarışıq saxlayan əhəngdaşının tərkibindəki $\mathrm{CaCO_{3}}$-ün tam parçalanmasından 134 qram bərk qalıq alınmışdır. Parçalanma zamanı alınan karbon qazının həcmini (litr, n.ş.) hesablayın. $\mathrm{A_{r}(Ca)=40,}$ $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, NULL::text, '33,6', '3', 'Əhəng daşının kütləsini x qram götürüb, hesablamaları aparaq 0,75x a $\mathrm{CaCO_{3}}$ t → $\mathrm{CaO + CO_{2}}$ 100 56 a= 0,42x q $\mathrm{CaO}$ 0,25x + 0,42x =134 x=200 0,75⋅200 b $\mathrm{CaCO_{3}}$ t → $\mathrm{CaO + CO_{2}}$ 100 22,4 b =33,6', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №56', 'KIM-0086_izah.png'),
  ('KIM-0091', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'qapali', 'Qarışıq Ayrılma üsulu etanol + su X X-i müəyyən edin.', 'KIM-0091.png', '{"A": "durultma", "B": "süzmə", "C": "kristallaşdırma", "D": "distillə", "E": "xromatoqrafiya"}', 'D', '3', 'Etanol suda həll olan mayedir və su ilə eynicinsli qarışıq əmələ gətirir. Məlumdur ki, bir birində həll olan maye maddələri bir-birindən ayırmaq üçün distillə üsulundan istifadə olunur.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №61', 'KIM-0091_izah.png'),
  ('KIM-0092', 'Ümumi kimya', 'Oksidləşmə-reduksiya reaksiyaları', 'qapali', '$\mathrm{KOH + Cl_{2}}$ t → $\mathrm{KCl + KClO_{3}+}$ $\mathrm{H_{2}O}$ reaksiyası üçün nə doğrudur? 1. $\mathrm{Cl_{2}}$ həm oksidləşdirici, həm də reduksiyaedicidir 2. $\mathrm{KCl}$ oksidləşmə məhsuludur 3. $\mathrm{KClO_{3}}$ reduksiyaedicidir', NULL::text, '{"A": "1, 3", "B": "yalnız 3", "C": "yalnız 2", "D": "yalnız 1", "E": "1, 2"}', 'D', '3', '$\mathrm{KOH + Cl_{2}}$ t → $\mathrm{KCl + KClO_{3} + H_{2}O}$ 0 -1 +5 Oksidləşmə dərəcəsinin dəyişməsinə görə $\mathrm{Cl_{2}}$ həm oksidləşdirici, həm də reduksiyaedicidir, $\mathrm{KCl}$ reduksiya məhsuludur, $\mathrm{KClO_{3}}$ oksidləşmə məhsuludur.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №62', 'KIM-0092_izah.png'),
  ('KIM-0093', 'Qeyri-üzvi kimya', 'Qeyri-üzvi maddələrin sinifləri', 'qapali', 'Hansı reaksiya nəticəsində alınan maddələrin hər ikisi natrium-hidroksid məhlulu ilə reaksiyaya daxil olur?', NULL::text, '{"A": "$\\mathrm{NH_{3} + O_{2}}$ t →", "B": "$\\mathrm{CaCO_{3}}$ t →", "C": "$\\mathrm{Mg(OH)_{2}}$ t →", "D": "$\\mathrm{H_{2}S + O_{2}}$ t →", "E": "$\\mathrm{FeS_{2} + O_{2}}$ t →"}', 'E', '3', 'A) $\mathrm{FeS_{2} + O_{2}}$ t → $\mathrm{Fe_{2}O_{3}+SO_{2}}$ B) $\mathrm{CaCO_{3}}$ t → $\mathrm{CaO}$ $\mathrm{+CO_{2}}$ C) $\mathrm{NH_{3} + O_{2}}$ t → $\mathrm{N_{2}}$ $\mathrm{+H_{2}O}$ D) $\mathrm{H_{2}S + O_{2}}$ t → $\mathrm{SO_{2}}$ $\mathrm{+H_{2}O}$ E) $\mathrm{Mg(OH)_{2}}$ t → $\mathrm{MgO}$ $\mathrm{+H_{2}O}$ Verilən reaksiya sxemlərində göründüyü kimi $\mathrm{FeS_{2} + O_{2}}$ t → $\mathrm{Fe_{2}O_{3}+SO_{2}}$ reaksiyasından alınan $\mathrm{Fe_{2}O_{3}}$ amfoter , $\mathrm{SO_{2}}$ isə turşu oksididir. Bu maddələrin ikisi $\mathrm{NaOH}$ məhlulu ilə reaksiyaya daxil olur.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №63', 'KIM-0093_izah.png'),
  ('KIM-0094', 'Qeyri-üzvi kimya', 'Karbon və silisium', 'qapali', 'Y-in suda məhlulu X $\mathrm{CO_{2}}$ X və Y maddələrini müəyyən edin. X Y', 'KIM-0094.png', '{"A": "$\\mathrm{NaCl}$ $\\mathrm{CaCO_{3}}$", "B": "$\\mathrm{KNO_{3}}$ $\\mathrm{Na_{2}CO_{3}}$", "C": "$\\mathrm{HCl}$ $\\mathrm{K_{2}CO_{3}}$", "D": "$\\mathrm{CaCO_{3}}$ $\\mathrm{K_{2}CO_{3}}$", "E": "$\\mathrm{K_{2}CO_{3}}$ $\\mathrm{CaCO_{3}}$"}', 'C', '3', 'Şərtə əsasən yalnız $\mathrm{K_{2}CO_{3}+2HCl \rightarrow KCl}$ $\mathrm{+CO_{2}}$ $\mathrm{+H_{2}O}$ reaksiyasında $\mathrm{CO_{2}}$ alınır.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №64', 'KIM-0094_izah.png'),
  ('KIM-0095', 'Qeyri-üzvi kimya', 'Metallar', 'qapali', 'm (Me), q 12 zaman → → 2,2 ν $\mathrm{(H_{2}),}$ mol 0,7 zaman Qələvi metalın xlorid turşusu ilə reaksiyasının qrafiklərinə əsasən metalın nisbi atom kütləsini hesablayın.', 'KIM-0095.png', '{"A": "39", "B": "24", "C": "1", "D": "23", "E": "7"}', 'E', '3', 'Qələvi metalların xlorid turşusu ilə reaksiyasını ümumi şəkildə 2Me+2HCl → 2MeCl + $\mathrm{H_{2}}$ tənliyi ilə ifadə edə bilərik. Tənliyə əsasən hesablama aparsaq $\mathrm{2A_{r}(Me)------------1}$ mol $\mathrm{H_{2}}$ 9,8 q Me-------0,7 mol $\mathrm{H_{2}}$ $\mathrm{A_{r}(Me)}$ =7. Metalın nisbi atom kütləsi 7-dir.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №65', 'KIM-0095_izah.png'),
  ('KIM-0097', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', 'Polikondensləşmə reaksiyası tənliyinin sxemini göstərin.', 'KIM-0097.png', '{"A": "$\\mathrm{OH}$ + nH C H → O n t, $\\mathrm{H^{+}}$", "B": "$\\mathrm{HOOC}$ $\\mathrm{COOH+CH_{3}CH_{2}OH}$ → t, $\\mathrm{H^{+}}$", "C": "$\\mathrm{CH_{3}COOH + HOCH_{2}CH_{2}OH}$ t, H → $\\mathrm{^{+}}$", "D": "$\\mathrm{nCH_{2}}$ $\\mathrm{CHCl}$ → t, p, kat", "E": "$\\mathrm{CH}$ $\\mathrm{CH_{2} + nCH_{2}}$ $\\mathrm{CH}$ $\\mathrm{CH}$ $\\mathrm{CH_{2}}$ → n t, p, kat"}', 'A', '3', '$\mathrm{OH}$ + nH C H → O n t, $\mathrm{H^{+}}$ reaksiyası üzrə fenol və formaldehid birlikdə polikondensləşərək polimerlərə aid olan fenolformaldehid qatranı və su əmələ gətirir.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №67', 'KIM-0097_izah.png'),
  ('KIM-0098', 'Ümumi kimya', 'Elektrolitik dissosiasiya və ion mübadiləsi', 'qapali', 'I. $\mathrm{CH_{3}COOH}$ və $\mathrm{NaOH}$ II. $\mathrm{Ba(OH)_{2},}$ $\mathrm{HCl}$ və $\mathrm{HNO_{3}}$ III. $\mathrm{HCl}$ və $\mathrm{KOH}$ Eyni həcmli və eyni molyar qatılıqlı verilmiş maddələrin məhlullarının qarışıqlarının hansılarında mühit neytraldır?', NULL::text, '{"A": "yalnız I", "B": "yalnız III", "C": "yalnız II", "D": "I, II, III", "E": "II, III"}', 'E', '3', 'I. $\mathrm{CH_{3}COOH + NaOH \rightarrow H_{2}O + CH_{3}COONa}$ (mühit qələvi) II $\mathrm{Ba(OH)_{2} + HCl + HNO_{3} \rightarrow BaCl(NO_{3}) + H_{2}O}$ (mühit neytral) III. $\mathrm{HCl + KOH \rightarrow KCl+H_{2}O}$ (mühit neytral)', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №68', 'KIM-0098_izah.png'),
  ('KIM-0099', 'Ümumi kimya', 'Reaksiyaların təsnifatı və istilik effekti', 'qapali', '$\mathrm{2H_{2}(q)+O_{2}(q)=2H_{2}O(m)+572}$ kC Termokimyəvi tənliyi üçün hansı ifadələr doğrudur? 1. Suyun əmələgəlmə istiliyi +286 kC/mol-dur 2. Reaksiyanın istilik effekti +286 kC-dur 3. Hidrogenin yanma istiliyi +286 kC/mol-dur 4. Suyun parçalanma reaksiyasının istilik effekti +572 kC-dur', NULL::text, '{"A": "2, 4", "B": "1, 3", "C": "2, 3", "D": "3, 4", "E": "1, 2, 3"}', 'B', '3', 'Verilmiş termokimyəvi tənliyə uyğun olaraq 1. Suyun əmələgəlmə istiliyi 572:2= +286 kC/mol-dur 2. Reaksiyanın istilik effekti 572 kC-dur 3. Hidrogenin yanma istiliyi 572:2= +286 kC/mol-dur 4. Suyun parçalanma reaksiyasının istilik effekti - 572 kC-dur', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №69', 'KIM-0099_izah.png'),
  ('KIM-0100', 'Qeyri-üzvi kimya', 'Kükürd və birləşmələri', 'qapali', '$\mathrm{Fe_{2}(SO_{4})_{3}}$ t → $\mathrm{Fe_{2}O_{3}+X}$ Hansı ifadə doğrudur?', NULL::text, '{"A": "reaksiya oksidləşmə-reduksiya reaksiyasıdır", "B": "X – $\\mathrm{SO_{2}}$-dir", "C": "X – sulfat turşusudur", "D": "kükürd atomu reduksiyaedicidir", "E": "X qələvilərlə reaksiyaya daxil olur"}', 'E', '3', 'Dəmir(III)sulfatın parçalanma reaksiyası: $\mathrm{Fe_{2}(SO_{4})_{3}}$ t → $\mathrm{Fe_{2}O_{3}+}$ $\mathrm{SO_{3}}$ kimidir. Reaksiya tənliyindən aydın olur ki, X maddəsi $\mathrm{SO_{3}}$-dür. $\mathrm{SO_{3}}$ turşu oksidi olduğu üçün qələvilərlə reaksiyaya daxil olur.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №70', 'KIM-0100_izah.png'),
  ('KIM-0101', 'Qeyri-üzvi kimya', 'Hidrogen, oksigen, su', 'qapali', '$\mathrm{X_{2}}$ $\mathrm{Fe}$ $\mathrm{HCl}$ $\mathrm{KMnO_{4}}$ $\mathrm{Y_{2}}$ $\mathrm{H_{2}O}$ 7 mol $\mathrm{X_{2}}$ və 3 mol $\mathrm{Y_{2}}$ tam reaksiyaya daxil olarsa, ilkin maddələrin birindən neçə mol artıq qalar?', 'KIM-0101.png', '{"A": "1", "B": "4", "C": "2", "D": "5", "E": "3"}', 'A', '3', '$\mathrm{Fe + 2HCl \rightarrow FeCl_{2}+}$ $\mathrm{H_{2}}$ $\mathrm{(X_{2})}$ 2 $\mathrm{KMnO_{4}t \rightarrow K_{2}MnO_{4} + MnO_{2}+}$ $\mathrm{O_{2}(Y_{2})}$ 6 3 $\mathrm{2H_{2} + O_{2} \rightarrow 2H_{2}O}$ 2 1 Tənliyə əsasən 7 mol $\mathrm{H_{2}}$ və 3 mol $\mathrm{O_{2}}$ tam reaksiyaya daxil olduqda, oksigenin hamısı sərf olunur və 1 mol $\mathrm{H_{2}(7-6=1)}$ artıq qalır', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №71', 'KIM-0101_izah.png'),
  ('KIM-0102', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'qapali', 't, kat → $\mathrm{CH_{3}}$ C O H $\mathrm{+H_{2}}$ X X-i müəyyən edin.', 'KIM-0102.png', '{"A": "etil spirti", "B": "dietil efiri", "C": "asetaldehid", "D": "sirkə turşusu", "E": "metil spirti"}', 'A', '3', 'Aldehidlərin hidrogenlə reaksiyasından molekulunda eyni sayda karbon atomu olan birli spirtlər alınır. t, kat → $\mathrm{CH_{3}}$ C O H $\mathrm{+H_{2}}$ reaksiyasından etil spirtinin $\mathrm{(C_{2}H_{5}OH)}$ alındığı məlum olur. $\mathrm{X=C_{2}H_{5}OH,}$ etil spirti.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №72', 'KIM-0102_izah.png'),
  ('KIM-0103', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'qapali', 'Maddə Homoloji sırada yeri Molekulunda karbon atomlarının sayı Doymuş alifatik keton 3 x x-i müəyyən edin.', 'KIM-0103.png', '{"A": "7", "B": "5", "C": "4", "D": "6", "E": "3"}', 'B', '3', 'Ketonlar $\mathrm{C_{n}H_{2n}O}$ ümumi formuluna malikdir. Doymuş alifatik ketonların homoloji sırasının birinci nümayəndəsinin molekulunda 3 karbon atomu var. Deməli, homoloji sıranın üçüncü nümayəndəsinin molekulunda 5 karbon atomu olacaq.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №73', 'KIM-0103_izah.png'),
  ('KIM-0106', 'Ümumi kimya', 'Məhlullar', 'qapali', '20%-li doymamış məhlul hazırlamaq üçün 40 q duzu neçə qram suda həll etmək lazımdır?', NULL::text, '{"A": "210", "B": "160", "C": "120", "D": "80", "E": "100"}', 'B', '3', 'Məsələnin şərtinə əsasən 40 q duz suda həll edildikdə 20% məhlul alınmışdır. Deməli bu məhlulun kütləcə 20 % duz 80 % isə sudur. Uyğun hesablama aparsaq 20%---------------40 q 80%-----------------x q x=160', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №76', 'KIM-0106_izah.png'),
  ('KIM-0108', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'qapali', 'Reaksiyaya daxil olan maddələr Həcmi, (l, n.ş.) Alınan karbamidin kütləsi, q $\mathrm{CO_{2}}$ 22,4 15 $\mathrm{NH_{3}}$ x İlkin maddələrdən biri tam reaksiyaya daxil olarsa, x-i hesablayın. $\mathrm{M_{r}((NH_{2})_{2}CO)=60}$', 'KIM-0108.png', '{"A": "28", "B": "33,6", "C": "11,2", "D": "24", "E": "44,8"}', 'C', '3', '44,8 litr 22,4 litr 60 2 $\mathrm{NH_{3} + CO_{2} \rightarrow CO(NH_{2})_{2}}$ $\mathrm{+H_{2}O}$ x litr 22,4 litr 15 verilən $\mathrm{CO_{2}}$ qaz artıq miqdarda götürülüb. Göründüyü kimi, 22,4 litr $\mathrm{CO_{2}}$-dən reaksiyaya 4 dəfə az, yəni 5,6 litr qaz daxil olur. 44,8 litr ------ 60 q CO(N $\mathrm{H_{2})_{2}}$ x litr -------- 15 q CO(N $\mathrm{H_{2})_{2}}$ / x=11,2 litr (n.ş) $\mathrm{NH_{3}}$ tam reaksiyaya daxil olur', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №78', 'KIM-0108_izah.png'),
  ('KIM-0110', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', 'Mürəkkəb efirlərə aid olan irimolekullu birləşməni göstərin.', NULL::text, '{"A": "sellüloza", "B": "kapron", "C": "təbii kauçuk", "D": "lavsan", "E": "polivinilxlorid"}', 'D', '3', 'Verilmiş iri molekullu birləşmələrdən yalnız lavsan efirləşmə reaksiyasından alınır. Lavsan makromolekulunda mürəkkəb efir qrupu var. Deməli, lavsan mürəkkəb efirlərə aid olan iri molekullu birləşmədir.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №80', 'KIM-0110_izah.png'),
  ('KIM-0111', 'Üzvi kimya', 'Alkenlər və alkadienlər', 'qapali', '$\mathrm{C_{n}H_{2n-2}}$ $\mathrm{+2H_{2},}$ t, kat. → X X molekulunda atomların ümumi sayını hesablayın.', NULL::text, '{"A": "2n+2", "B": "3n", "C": "3n+2", "D": "3n–2", "E": "2n–2"}', 'C', '3', '$\mathrm{C_{n}H_{2n-2}}$ $\mathrm{+2H_{2},}$ t, kat. → CnH2n+2 X $\mathrm{-C_{n}H_{2n+2}}$ tərkibli karbohidrogendir. Onun molekulunda atomların ümumi sayı ( n+2n+2 =3n+2) 3n+2 cəmindən ibarətdir.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №81', 'KIM-0111_izah.png'),
  ('KIM-0112', 'Ümumi kimya', 'Reaksiya sürəti və kimyəvi tarazlıq', 'qapali', 'Temperaturun artması ilə reaksiyanın getmə müddəti 3 dəfə azalarsa, kimyəvi reaksiyanın sürəti necə dəyişər?', NULL::text, '{"A": "dəyişməz", "B": "3 dəfə azalar", "C": "3 dəfə artar", "D": "9 dəfə artar", "E": "9 dəfə azalar"}', 'C', '3', 'Bildiyimiz kimi, $\mathrm{\upsilon _{t2/}\upsilon _{t1=}\tau _{1/}\tau _{2}}$ Buna görə, reaksiyanın sürəti getmə müddəti 3 dəfə azalarsa, sürəti 3 dəfə artar', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №82', 'KIM-0112_izah.png'),
  ('KIM-0113', 'Üzvi kimya', 'Alkanlar', 'aciq_eded', '15 q alkanın tam yanmasından 44 q karbon $\mathrm{(IV)}$ oksid ayrılmışsa, reaksiyadan neçə qram su alınar? $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(H)=1,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, NULL::text, '27', '3', 'Molekulunda n sayda karbon atomu olan alkanın bir molunun tam yanma tənliyi aşağıdakı kimidir. CnH2n+2 + 3 → 1 2 n $\mathrm{+\cdot O_{2}}$ $\mathrm{nCO_{2} + (n+1)H_{2}O}$ Reaksiya tənliyinə əsasən uyğun hesablamaları aparaq 14n+2 q alkan ---------------44n q $\mathrm{CO_{2}}$ 15 q alkan -----------------44 q $\mathrm{CO_{2}}$ n=2 deməli alkan $\mathrm{C_{2}H_{6}}$ dır. 15 q etanın tam yanmasından alınan suyun kütləsini (q) hesablayaq $\mathrm{C_{2}H_{6} \rightarrow 3H_{2}O}$ 30 q $\mathrm{C_{2}H_{6}-----------54}$ q $\mathrm{H_{2}O}$ 15 q $\mathrm{C_{2}H_{6}------------x}$ q $\mathrm{H_{2}O}$ x=27', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №83', 'KIM-0113_izah.png'),
  ('KIM-0114', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'aciq_eded', '→ $\mathrm{CuO}$, t → $\mathrm{+C^{2}H^{5}OH}$ 2 $\mathrm{C_{2}H_{5}-CH-CH_{3}}$ + 3 + $\mathrm{CH_{3}-CH-CH_{3}}$ 1 5 4 $\mathrm{+CH_{3}CH_{2}CH_{2}OH}$ $\mathrm{CH_{3}OH+}$ $\mathrm{OH}$ $\mathrm{OH}$ Hansı reaksiyalarda keton alınır?', 'KIM-0114.png', NULL::text, '1,3', '3', 'Məlumdur ki, ikili spirtlərin $\mathrm{CuO}$ ilə reaksiyasından ketonlar alınır. Verilmiş reaksiyalardan yalnız birinci və üçüncü reaksiyalarda götürülən spirtlər ikilidir. Deməli, birinci və üçüncü reaksiyalardan keton alınacaq.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №84', 'KIM-0114_izah.png'),
  ('KIM-0115', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'aciq_eded', '$\mathrm{C_{x}H_{y}O_{z}+}$ $\mathrm{4O_{2} \rightarrow 3CO_{2}+}$ $\mathrm{4H_{2}O}$ tənliyinə əsasən $\mathrm{C_{x}H_{y}O_{z}}$-in 1 molekulunda neçə atom var?', NULL::text, NULL::text, '13', '3', '$\mathrm{C_{x}H_{y}O_{z}+}$ $\mathrm{4O_{2} \rightarrow 3CO_{2}+}$ $\mathrm{4H_{2}O}$ reaksiya tənliyinin əmsallaşdırılmış formasından aydın olur ki, $\mathrm{C_{x}H_{y}O_{z}}$ maddəsinin molekulunda 3 karbon, 8 hidrogen və 2 oksigen atomu var.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №85', 'KIM-0115_izah.png'),
  ('KIM-0116', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'aciq_eded', '44,8 l (n.ş.) azotdan neçə qram 60%-li nitrat turşusu almaq olar? $\mathrm{M_{r}(HNO_{3})=63}$', NULL::text, NULL::text, '420', '3', 'Azotdan nitrat turşusunun alınması sadə sxemlə ifadə etsək $\mathrm{N_{2} \rightarrow 2HNO_{3}}$ 22,4 litr (n.ş) $\mathrm{N_{2}---------126}$ q $\mathrm{HNO_{3}}$ alınır 44,8 litr (n.ş) $\mathrm{N_{2}}$ -----------x q $\mathrm{HNO_{3}}$ x= 252 q 252-------------60% y ---------------100% y=420 q', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №86', 'KIM-0116_izah.png')
       ) as v(code, section, topic, type, body, image_path, options, correct, difficulty, solution,
              groups, year, source_ref, solution_image_path)
  join subjects s on s.slug = 'kimya'
  join topics sec on sec.subject_id = s.id and sec.parent_id is null and sec.name = v.section
  join topics t on t.subject_id = s.id and t.parent_id = sec.id and t.name = v.topic
on conflict (code) do update set
  topic_id = excluded.topic_id, type = excluded.type, body = excluded.body, image_path = excluded.image_path,
  options = excluded.options, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty,
  solution = excluded.solution, exam_levels = excluded.exam_levels, groups = excluded.groups,
  year = excluded.year, source = excluded.source, source_ref = excluded.source_ref,
  is_active = excluded.is_active, solution_image_path = excluded.solution_image_path;

-- 4) every approved question must now exist (a missing topic would silently drop a row from the join)
do $$
declare n integer;
begin
  select count(*) into n from questions where code in ('KIM-0001', 'KIM-0002', 'KIM-0003', 'KIM-0004', 'KIM-0007', 'KIM-0008', 'KIM-0011', 'KIM-0012', 'KIM-0013', 'KIM-0014', 'KIM-0015', 'KIM-0016', 'KIM-0017', 'KIM-0018', 'KIM-0019', 'KIM-0020', 'KIM-0021', 'KIM-0023', 'KIM-0024', 'KIM-0026', 'KIM-0031', 'KIM-0032', 'KIM-0033', 'KIM-0034', 'KIM-0035', 'KIM-0036', 'KIM-0037', 'KIM-0038', 'KIM-0039', 'KIM-0040', 'KIM-0041', 'KIM-0042', 'KIM-0046', 'KIM-0048', 'KIM-0049', 'KIM-0051', 'KIM-0053', 'KIM-0055', 'KIM-0061', 'KIM-0062', 'KIM-0063', 'KIM-0064', 'KIM-0068', 'KIM-0069', 'KIM-0070', 'KIM-0071', 'KIM-0072', 'KIM-0073', 'KIM-0074', 'KIM-0079', 'KIM-0080', 'KIM-0081', 'KIM-0082', 'KIM-0083', 'KIM-0084', 'KIM-0085', 'KIM-0086', 'KIM-0091', 'KIM-0092', 'KIM-0093', 'KIM-0094', 'KIM-0095', 'KIM-0097', 'KIM-0098', 'KIM-0099', 'KIM-0100', 'KIM-0101', 'KIM-0102', 'KIM-0103', 'KIM-0106', 'KIM-0108', 'KIM-0110', 'KIM-0111', 'KIM-0112', 'KIM-0113', 'KIM-0114', 'KIM-0115', 'KIM-0116');
  if n <> 78 then
    raise exception 'Gözlənilən 78 sual, bazada % tapıldı: geri alınır', n;
  end if;
end $$;

commit;

-- 5) result
select s.name as fenn, count(*) as sual_sayi
  from questions q
  join topics t on t.id = q.topic_id
  join subjects s on s.id = t.subject_id
 where s.slug = 'kimya' and q.source = 'DİM'
 group by s.name;
